create table public.provider_settings (provider text primary key check (provider in ('openrouter','gemini','nvidia','groq','cerebras','openai')), model text not null check (length(model) between 1 and 200), encrypted_key text not null check (length(encrypted_key) between 65 and 16500), enabled boolean not null default false, updated_at timestamptz not null default now()); alter table public.provider_settings enable row level security; revoke all on public.provider_settings from public, anon, authenticated; grant select,insert,update,delete on public.provider_settings to service_role;